// Peacock — the achievements vanilla triggers cannot see (the tab itself is generated by tools/gen-advancements.py).
//
// Granted here: every boss (anyone who hit it and is within 128 blocks when it dies, like the Blueprint drops;
// Incendium's bosses are vanilla mobs with a name), "every boss that holds a Blueprint", Blueprints learned (first,
// each tier, all), joining a town (a Village Recruits faction is a scoreboard team named village_…), a first recruit
// (a Recruits soldier near you that you own), a sealed rumour opened, and a winter lived through to spring.
//
// The BOSSES table must match tools/gen-advancements.py, which prints it.
// Rhino notes (see tools/validate.py): `var` inside functions, no `const`/`let` in try blocks, no Math constants.
;(() => {
const BOSSES = {
  'mutantmonsters:mutant_zombie': ['mutant_zombie', true],
  'mutantmonsters:mutant_skeleton': ['mutant_skeleton', true],
  'mutantmonsters:mutant_creeper': ['mutant_creeper', true],
  'mutantmonsters:mutant_snow_golem': ['mutant_snow_golem', true],
  'mutantmonsters:mutant_enderman': ['mutant_enderman', false],
  'minecraft:skeleton|Torte': ['torte', true],
  'mowziesmobs:ferrous_wroughtnaut': ['ferrous_wroughtnaut', true],
  'mowziesmobs:naga': ['naga', true],
  'mowziesmobs:umvuthi': ['umvuthi', true],
  'illagerinvasion:invoker': ['invoker', true],
  'mowziesmobs:frostmaw': ['frostmaw', true],
  'mowziesmobs:sculptor': ['sculptor', false],
  'minecraft:wither_skeleton|Radiation Director': ['radiation_director', true],
  'cataclysm:the_leviathan': ['leviathan', true],
  'cataclysm:netherite_monstrosity': ['netherite_monstrosity', true],
  'cataclysm:the_harbinger': ['harbinger', true],
  'cataclysm:ignis': ['ignis', true],
  'cataclysm:ender_guardian': ['ender_guardian', true],
  'cataclysm:ancient_remnant': ['ancient_remnant', false],
  'cataclysm:maledictus': ['maledictus', false],
  'cataclysm:scylla': ['scylla', false],
  'minecraft:blaze|Hovering Inferno': ['hovering_inferno', false],
  'illageandspillage:spiritcaller': ['spiritcaller', false],
  'illageandspillage:magispeller': ['magispeller', false],
  'illageandspillage:freakager': ['freakager', false],
  'illageandspillage:ragno': ['ragno', false],
  'minecraft:elder_guardian': ['elder_guardian', false],
  'minecraft:warden': ['warden', false],
  'minecraft:wither': ['wither', false],
  'minecraft:ender_dragon': ['ender_dragon', false],
}
const TYPES = {}
Object.keys(BOSSES).forEach(k => { TYPES[k.split('|')[0]] = true })
const LEDGER = Object.keys(BOSSES).filter(k => BOSSES[k][1]).map(k => BOSSES[k][0])
const FIGHTERS = 'peacock_adv_fighters'
const EVERY = 100          // ticks between the per-player checks

function adv(path) { return 'peacock:' + path }
function done(p, path) { try { return p.isAdvancementDone(adv(path)) } catch (e) { return false } }
function grant(p, path) { if (!done(p, path)) p.unlockAdvancement(adv(path)) }

function bossKey(entity) {
  var type = String(entity.type)
  if (!TYPES[type]) return null
  if (BOSSES[type]) return type
  var name = entity.hasCustomName() ? String(entity.customName.getString()) : ''
  var keys = Object.keys(BOSSES)
  for (var i = 0; i < keys.length; i++) {
    var parts = keys[i].split('|')
    if (parts.length > 1 && parts[0] === type && name.indexOf(parts[1]) >= 0) return keys[i]
  }
  return null
}

// ---------------------------------------------------------------- bosses
EntityEvents.hurt(event => {
  var boss = event.entity
  if (!TYPES[String(boss.type)]) return
  var attacker = event.source.actual
  if (!attacker || !attacker.isPlayer()) return
  var uuid = String(attacker.uuid)
  var list = boss.persistentData.getString(FIGHTERS)
  if (list.indexOf(uuid) >= 0) return
  boss.persistentData.putString(FIGHTERS, list ? list + ',' + uuid : uuid)
})

EntityEvents.death(event => {
  var boss = event.entity
  var key = bossKey(boss)
  if (!key) return
  var id = BOSSES[key][0]
  var level = boss.level
  var uuids = (boss.persistentData.getString(FIGHTERS) || '').split(',').filter(s => s.length)
  var killer = event.source.actual
  if (killer && killer.isPlayer() && uuids.indexOf(String(killer.uuid)) < 0) uuids.push(String(killer.uuid))
  uuids.forEach(u => {
    try {
      var p = level.server.getPlayerList().getPlayer(UUID.fromString(u))
      if (!p || String(p.level.dimension) !== String(level.dimension) || p.distanceTo(boss) > 128) return
      grant(p, 'bosses/first')
      grant(p, 'bosses/' + id)
      if (!done(p, 'bosses/ledger') && LEDGER.every(b => done(p, 'bosses/' + b))) grant(p, 'bosses/ledger')
    } catch (e) { console.warn('[peacock] achievements: ' + e) }
  })
})

// ---------------------------------------------------------------- the rest, checked every few seconds
function blueprints(p) {
  var L = global.LADDER
  if (!L) return
  var tiers = {}, learned = 0, total = 0
  Object.keys(L).forEach(rung => {
    var t = L[rung].tier
    if (!tiers[t]) tiers[t] = [0, 0]
    tiers[t][1]++
    total++
    if (p.stages.has('peacock_' + rung)) { tiers[t][0]++; learned++ }
  })
  if (learned > 0) grant(p, 'blueprints/first')
  Object.keys(tiers).forEach(t => { if (tiers[t][1] > 0 && tiers[t][0] === tiers[t][1]) grant(p, 'blueprints/tier' + t) })
  if (total > 0 && learned === total) grant(p, 'blueprints/all')
}

function swornIn(p) {
  if (done(p, 'towns/sworn_in')) return
  var team = p.getTeam()
  if (team && String(team.getName()).indexOf('village_') === 0) grant(p, 'towns/sworn_in')
}

function firstRecruit(p) {
  if (done(p, 'towns/first_recruit')) return
  var me = String(p.uuid)
  var near = p.level.getEntitiesWithin(p.boundingBox.inflate(16))
  for (var i = 0; i < near.size(); i++) {
    var e = near.get(i)
    if (String(e.type).indexOf('recruits:') !== 0) continue
    try {
      var owner = e.getOwnerUUID()
      if (owner && String(owner) === me) { grant(p, 'towns/first_recruit'); return }
    } catch (err) { }
  }
}

function season(server) {
  try {
    var helper = Java.loadClass('sereneseasons.api.season.SeasonHelper')
    return String(helper.getSeasonState(server.overworld()).getSeason())
  } catch (e) { return '' }
}

function winter(p, s) {
  if (done(p, 'survival/winter')) return
  if (s === 'WINTER') p.persistentData.putBoolean('peacock_saw_winter', true)
  else if (s === 'SPRING' && p.persistentData.getBoolean('peacock_saw_winter')) grant(p, 'survival/winter')
}

ServerEvents.tick(event => {
  var server = event.server
  if (server.tickCount % EVERY !== 0) return
  var s = server.tickCount % (EVERY * 12) === 0 ? season(server) : ''
  server.players.forEach(p => {
    try {
      blueprints(p)
      swornIn(p)
      firstRecruit(p)
      if (s) winter(p, s)
    } catch (e) { console.warn('[peacock] achievements: ' + e) }
  })
})

ItemEvents.rightClicked('peacock:rumour_voucher', event => {
  try { grant(event.player, 'towns/rumour') } catch (e) { }
})
})()
